from typing import Callable

def statements(k: int, n: int) -> int:
    """Number of statements of length exactly n."""
    return k ** n

def S(k: int, n: int) -> int:
    """Number of statements of length <= n: sum_{i=0}^n k^i."""
    return sum(k ** i for i in range(n + 1))

def verify_closed_form(k: int, n: int) -> bool:
    """Check (k-1) * S(k,n) == k^(n+1) - 1."""
    return (k - 1) * S(k, n) == k ** (n + 1) - 1

def verify_sandwich(k: int, n: int) -> bool:
    """Check k^n <= S(k,n) <= k^(n+1)."""
    return k ** n <= S(k, n) <= k ** (n + 1)

if __name__ == "__main__":
    k = 3
    for n in range(9):
        print(n, S(k, n), verify_closed_form(k, n), verify_sandwich(k, n))

from typing import Callable

def order_parameter(prov: Callable[[int], float], tot: Callable[[int], float], n: int) -> float:
    return prov(n) / tot(n)

def run(k: float = 3.0, a: float = 2.0, C: float = 1.0) -> None:
    tot: Callable[[int], float] = lambda n: k ** n
    prov: Callable[[int], float] = lambda n: C * a ** n
    for n in range(0, 35, 5):
        r = order_parameter(prov, tot, n)
        bound = C * (a / k) ** n
        print(f"n={n:2d}  r={r:.6e}  bound={bound:.6e}")
    print(f"a/k = {a/k:.3f} < 1  =>  r(n) -> 0")

if __name__ == "__main__":
    run()

import math
from typing import Callable

def growth_rate(tot: Callable[[int], float], n: int) -> float:
    return math.log(tot(n)) / n

def length_dist(k: float, n: int) -> float:
    return (k - 1.0) / k ** (n + 1)

def run(k: float = 3.0) -> None:
    tot: Callable[[int], float] = lambda n: k ** n
    for n in (1, 5, 10, 20, 40):
        print(f"n={n:3d}  log(tot n)/n = {growth_rate(tot, n):.8f}   log k = {math.log(k):.8f}")
    total = sum(length_dist(k, n) for n in range(60))
    print(f"sum p(n) ~ {total:.10f}  (converges to 1)")

if __name__ == "__main__":
    run()

