function CUMULATIVE_COUNT(k, n):
    if k == 1:
        return n + 1                     # degenerate alphabet
    numerator <- POW(k, n + 1) - 1        # fast exponentiation, O(log n)
    return numerator / (k - 1)            # exact integer division

function VERIFY(k, n):
    assert (k - 1) * CUMULATIVE_COUNT(k, n) == POW(k, n + 1) - 1
    assert POW(k, n) <= CUMULATIVE_COUNT(k, n) <= POW(k, n + 1)

