def cumulative_count(k: int, n: int) -> int:
    """Number of statements of length <= n via the geometric closed form.

    Uses (k-1)*S(k,n) = k^(n+1) - 1, so S is computed with one fast
    exponentiation instead of an O(n) summation.
    """
    if k == 1:
        return n + 1
    return (k ** (n + 1) - 1) // (k - 1)

def verify(k: int, n: int) -> bool:
    """Confirm the closed form and the sandwich bounds."""
    s = cumulative_count(k, n)
    return ((k - 1) * s == k ** (n + 1) - 1) and (k ** n <= s <= k ** (n + 1))

