function DENSITY_ZERO_CUTOFF(k, a, C, eps):
    require 0 <= a < k and eps > 0
    ratio <- a / k                        # in [0,1)
    # need C * ratio^N < eps  =>  N > log(eps/C)/log(ratio)
    if C <= eps:
        return 0
    N <- ceil( log(eps / C) / log(ratio) )
    return max(N, 0)

function ORDER_PARAMETER(prov, tot, n):
    return prov(n) / tot(n)

