import math
from typing import Callable

def order_parameter(prov: Callable[[int], float], tot: Callable[[int], float], n: int) -> float:
    return prov(n) / tot(n)

def density_zero_cutoff(k: float, a: float, C: float, eps: float) -> int:
    """Smallest N with the bound C*(a/k)^N < eps, certifying r(n) -> 0."""
    assert 0.0 <= a < k and eps > 0.0
    if C <= eps:
        return 0
    ratio = a / k
    return max(0, math.ceil(math.log(eps / C) / math.log(ratio)))

