import math

def logistic(beta: float, x_c: float, x: float) -> float:
    return 1.0 / (1.0 + math.exp(-(beta * (x - x_c))))

def critical_window_width(beta: float, eps: float) -> float:
    """Width of { x : eps < Phi_beta(x) < 1-eps }; scales like 1/beta."""
    assert beta > 0.0 and 0.0 < eps < 0.5
    return (2.0 / beta) * math.log((1.0 - eps) / eps)

