import math
from typing import Callable

def dimension_estimate(tot: Callable[[int], float], n: int) -> float:
    """log(tot n)/n, converging to the dimension log k."""
    return math.log(tot(n)) / n

def length_weight(k: float, n: int) -> float:
    """Length-distribution weight p(n) = (k-1)/k^(n+1)."""
    return (k - 1.0) / k ** (n + 1)

def normalization(k: float, N: int) -> float:
    """Truncated sum of the length distribution; -> 1 as N -> oo."""
    return sum(length_weight(k, n) for n in range(N + 1))
